css:
.resume{width: 210mm;
      min-height: 297mm;
      background: #ffffff;
      box-shadow: 0 12px 40px rgba(0,0,0,0.5);
      padding: 17mm 18mm 17mm 18mm; 
      display: flex;
      flex-direction: column;
      gap: 0.8rem;
      page-break-after: avoid;
      page-break-inside: avoid;}
.resume h1, .resume h2, .resume h3, .resume p, .resume li, .resume div, .resume span{font-family: 'Courier New', 'SF Mono', 'Menlo', 'Consolas', '思源黑体', 'Noto Sans SC', monospace;}
.header{margin-bottom: 0.4rem;
      border-bottom: 1.5px solid #4a4a4a;
      padding-bottom: 0.9rem;}
.name{font-size: 2.5rem;
      font-weight: 600;
      letter-spacing: 2px;
      color: #1e1e1e;
      line-height: 1.2;
      margin-bottom: 0.25rem;}
.title-line{font-size: 1rem;
      font-weight: 400;
      color: #5a5a5a;
      letter-spacing: 1px;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: baseline;
      margin-top: 0.2rem;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 1.8rem;
      font-size: 0.8rem;
      color: #4a4a4a;
      margin-top: 0.4rem;
      align-items: center;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;}
.icon{font-size: 0.9rem;
      color: #3a3a3a;
      font-weight: 500;}
.section-title{font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 2.5px;
      text-transform: uppercase;
      color: #2b2b2b;
      border-bottom: 1px solid #b0b0b0;
      padding-bottom: 0.25rem;
      margin-bottom: 0.7rem;
      margin-top: 0.5rem;}
.entry{margin-bottom: 0.75rem;}
.entry-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.15rem;}
.entry-left{font-weight: 700;
      font-size: 1rem;
      color: #1e1e1e;}
.entry-right{font-size: 0.8rem;
      color: #5a5a5a;
      font-weight: 500;
      white-space: nowrap;}
.entry-sub{font-size: 0.9rem;
      color: #3a3a3a;
      margin-bottom: 0.25rem;
      font-style: italic;
      font-weight: 500;}
.desc-list{list-style: none;
      padding-left: 0;
      margin-top: 0.2rem;}
.desc-list li{font-size: 0.8rem;
      color: #2d2d2d;
      margin-bottom: 0.18rem;
      display: flex;
      align-items: baseline;
      gap: 0.4rem;}
.desc-list li::before{content: "–";  
      color: #606060;
      font-weight: 600;
      display: inline-block;
      width: 0.9rem;
      text-align: center;
      flex-shrink: 0;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-top: 0.3rem;}
.skill-tag{background: #f0f0f0;
      color: #1e1e1e;
      padding: 0.15rem 0.7rem;
      font-size: 0.75rem;
      border: 1px solid #c0c0c0;
      letter-spacing: 0.3px;
      font-weight: 500;}
.two-col{display: flex;
      gap: 1.8rem;
      margin-top: 0.2rem;}
.col{flex: 1;}
.col p{font-size: 0.8rem;
      margin-bottom: 0.25rem;
      display: flex;
      justify-content: space-between;}
.project-item{margin-bottom: 0.6rem;}
.project-name{font-weight: 700;
      font-size: 0.9rem;
      color: #1e1e1e;
      display: flex;
      justify-content: space-between;}
.project-desc{font-size: 0.8rem;
      color: #3a3a3a;
      margin-top: 0.1rem;}
.resume hr{border: none;
      border-top: 1px solid #d0d0d0;
      margin: 0.4rem 0 0.7rem 0;}

.resume{font-family:"Courier New","Source Code Pro","Menlo","Consolas","思源黑体","Noto Sans SC",monospace;color:#2d2d2d;line-height:1.5}.summary{font-size:0.8rem;color:#2d2d2d;line-height:1.5}.edu-row{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap}.edu-left{font-weight:700;font-size:0.9rem}.edu-right{font-size:0.8rem;color:#4a4a4a}.edu-note{font-size:0.8rem;color:#3a3a3a;margin-bottom:0.2rem}.cert-label{font-weight:600}
